 for(const s of [-1,1]){roundBox(body,mat(0xf4ebc1,{emissive:0x66603a}),s*.57,.78,len*.5+.025,.39,.19,.06);roundBox(body,metal,s*.91,1.05,.55,.2,.10,.26);}
 roundBox(body,metal,0,.48,len*.5+.07,1.79,.14,.12);roundBox(body,metal,0,.48,-len*.5-.07,1.79,.14,.12);roundBox(body,mat(0xf4f0cb),0,.64,-len*.5-.075,.48,.17,.02);
 if(type==='taxi'){roundBox(body,mat(0xe2bf5c),0,1.75,-.12,.65,.22,.36);}
 const wheels=[];for(const x of [-.91,.91])for(const z of [-1.17,1.17]){const w=new THREE.Group();w.position.set(x,.39,z);g.add(w);let tire=new THREE.Mesh(new THREE.CylinderGeometry(.36,.36,.22,renderer.isSoftwareRenderer?10:20),rubber);tire.rotation.z=Math.PI/2;tire.castShadow=true;w.add(tire);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.19,.19,.235,10),metal);hub.rotation.z=Math.PI/2;w.add(hub);wheels.push(w);}
