function createPeds(){for(let i=0;i<16;i++){const p=makeCharacter(i%3,true);Object.assign(p,{lat:i%2?.115:-.115,lon:.23+i*TAU/16,heading:Math.PI/2,speed:.65+rng()*.45,down:0,panic:0});actorGroup.add(p.root);place(p.root,p.lat,p.lon,p.heading);p.gun.visible=false;peds.push(p);}}
function createTargets(){for(let i=0;i<4;i++){const g=new THREE.Group(),poleMat=mat(0x6a8174),cyan=basic(0xa4eec3),orange=mat(0xd6a779);let pole=cyl(g,poleMat,0,.72,0,.065,1.44);box(g,orange,0,.14,0,.7,.22,.7);const face=new THREE.Group();face.position.y=1.6;face.rotation.y=-Math.PI/2;g.add(face);for(const r of [.44,.25])face.add(new THREE.Mesh(new THREE.TorusGeometry(r,.044,6,24),cyan));orb(face,cyan,0,0,0,.08);const t={lat:[-.23,-.03,.19,.37][i],lon:i%2?.167:-.167,root:g,face,hitTimer:0,hp:1,kind:'target'};actorGroup.add(g);place(g,t.lat,t.lon);targets.push(t);}}
function collides(lat,lon,radius=.34){const p=nAt(lat,lon).multiplyScalar(R);for(const b of buildings){if(p.distanceToSquared(b.center)>190)continue;const d=p.clone().sub(b.center);if(Math.abs(d.dot(b.e))<b.w*.5+radius&&Math.abs(d.dot(b.f))<b.d*.5+radius)return b;}return null;}
function moveWithCollision(a,heading,meters,radius=.35){if(Math.abs(meters)<.00001)return 0;const next=movePoint(a,heading,meters);if(!collides(next.lat,next.lon,radius)){a.lat=next.lat;a.lon=next.lon;return Math.abs(meters);}if(!collides(next.lat,a.lon,radius)){const d=Math.abs(next.lat-a.lat)*R;a.lat=next.lat;return d;}if(!collides(a.lat,next.lon,radius)){const d=Math.abs(wrap(next.lon-a.lon))*R*Math.cos(a.lat);a.lon=next.lon;return d;}return 0;}
function updateLabels(){const d=themes[cityId];$('characterLabel').textContent=characterDefs[charId].name;$('cityLabel').textContent=d.name;$('districtName').textContent=d.district;$('worldCoord').textContent=d.coord;$('coverCity').textContent=d.title;$('coverSub').textContent=d.subtitle;document.querySelectorAll('[data-char]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.char)===charId));document.querySelectorAll('[data-city]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.city)===cityId));}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800);}
function addHeat(n){wanted=clamp(wanted+n,0,5);heatAge=0;}
function hurt(amount){health=Math.max(0,health-amount);$('damage').style.opacity='.4';setTimeout(()=>$('damage').style.opacity='0',180);if(health<=0){cash=Math.max(0,cash-100);resetPlayer(false);toast('休整后回到街区 · 医疗费 $100');}updateHUD();}
function setWeaponV4(id,notify=true){weapon=(id+weapons.length)%weapons.length;reloadTime=0;if(player){player.gun.visible=weapon>0;player.pistol.visible=weapon===2;player.smg.visible=weapon===3;player.bat.visible=weapon===1;}if(notify)toast('已装备 '+weapons[weapon].name);updateHUD();}
function enterExitGround(){if(!started||menuOpen||orbit)return;if(activeCar){const c=activeCar;c.player=false;c.occupied=false;c.traffic=false;c.speed*=.2;c.driver.visible=false;let success=false;for(const sign of [-1,1]){const p=movePoint(c,c.heading+sign*Math.PI/2,1.9);if(!collides(p.lat,p.lon,.4)){player.lat=p.lat;player.lon=p.lon;success=true;break;}}if(!success){player.lat=c.lat;player.lon=c.lon;}player.heading=c.heading;player.root.visible=true;activeCar=null;viewYaw=player.heading;toast('已下车 · '+(missionStage===2?'换上手枪，寻找青色训练靶':'继续探索这颗小星球'));audio('switch');}
 else{findNearestCar();if(!nearestCar){toast('靠近车辆后再上车');return;}const c=nearestCar;if(c.disabled>0){toast('这辆车正在维修，换一辆试试');return;}const stolen=c.occupied;if(stolen){addHeat(1);stolenCount++;let p=makeCharacter(Math.floor(rng()*3),true);const pos=movePoint(c,c.heading-Math.PI/2,2);Object.assign(p,{lat:pos.lat,lon:pos.lon,heading:c.heading+Math.PI,speed:2,down:0,panic:8});actorGroup.add(p.root);peds.push(p);toast('抢车成功 · 警方注意到了你 ★');}else toast('已上车 · W 加速，A / D 转向，空格刹车');Object.assign(c,{player:true,occupied:true,traffic:false});c.driver.visible=true;activeCar=c;player.root.visible=false;player.lat=c.lat;player.lon=c.lon;viewYaw=c.heading;if(missionStage===0)missionStage=1;audio('switch');}
 updateHUD();}
function findNearestCar(){nearestCar=null;let min=5.0;for(const c of cars){if(c.disabled>0)continue;const d=distance(player,c);if(d<min){min=d;nearestCar=c;}}return nearestCar;}
function reload(){if(weapons[weapon].melee||weapon<2||reloadTime>0)return;reloadTime=1.15;toast('正在装填…');audio('switch');}
function pickTarget(){if(activeCar)return null;const w=weapons[weapon];let best=null,score=Infinity;const maxAngle=weapon<2?.05:.62;const f=frame(player.lat,player.lon,player.heading),origin=nAt(player.lat,player.lon).multiplyScalar(R+1.25);for(const t of [...targets,...peds.filter(p=>p.down<=0&&!p.inTaxi&&p.root.visible),...cars.filter(c=>c.disabled<=0&&c!==activeCar)]){const kind=t.kind==='target'?'target':t.wheels?'car':'ped';const range=distance(player,t);if(range>w.range||range<.25)continue;const p=nAt(t.lat,t.lon).multiplyScalar(R+(kind==='target'?1.6:1.1));const delta=p.clone().sub(origin);const tangent=delta.clone().addScaledVector(f.n,-delta.dot(f.n)).normalize();const dot=tangent.dot(f.f);if(dot<maxAngle)continue;const ray=new THREE.Raycaster(origin,delta.clone().normalize(),.1,delta.length()-.3);if(ray.intersectObjects(buildingMeshes,false).length)continue;const s=range+(1-dot)*8+(kind==='target'?-2:0);if(s<score){score=s;best={object:t,kind,point:p};}}return best;}
function spawnLine(start,end,color=0xffe1a3){const geometry=new THREE.BufferGeometry().setFromPoints([start,end]);const line=new THREE.Line(geometry,basic(color,{transparent:true,opacity:.94}));scene.add(line);fx.push({root:line,time:.12,max:.12,type:'line'});}
function sparks(pos,color=0xffd49b,count=6){for(let i=0;i<count;i++){let s=new THREE.Mesh(sphereGeo,basic(color));s.scale.setScalar(.055+rng()*.04);s.position.copy(pos);scene.add(s);fx.push({root:s,time:.24+rng()*.22,max:.4,velocity:V(rng()-.5,rng()-.5,rng()-.5).multiplyScalar(4),type:'spark'});}}
function attackV4(){if(!started||menuOpen||orbit||activeCar||cooldown>0||reloadTime>0)return;const w=weapons[weapon];if(ammo[weapon]<=0){reload();return;}cooldown=w.rate;attackTime=weapon<2?.3:.13;if(weapon>=2)ammo[weapon]--;const aim=pickTarget();let a=frame(player.lat,player.lon,player.heading),start=weaponOrigin(a);let end=aim?aim.point:start.clone().addScaledVector(a.f,w.range).addScaledVector(a.n,-w.range*.09);
 if(weapon>=2){const ray=new THREE.Raycaster(start,end.clone().sub(start).normalize(),.1,start.distanceTo(end));const hit=ray.intersectObjects(buildingMeshes,false)[0];if(hit&&(!aim||hit.distance<start.distanceTo(aim.point)-.4)){end=hit.point;aimTarget=null;sparks(end);spawnLine(start,end);addHeat(.10);audio('shot');updateHUD();return;}spawnLine(start,end);sparks(start,0xffe8a1,2);audio(weapon===3?'smg':'shot');}else audio('melee');
 if(aim){let t=aim.object;if(aim.kind==='target'){if(t.hitTimer<=0){t.hitTimer=1.4;targetHits++;cash+=20;sparks(aim.point,0xb4f5c5,9);toast('命中训练靶 +$20 · '+Math.min(targetHits,3)+'/3');if(missionStage===2&&targetHits>=3)completeMission();}}
 else if(aim.kind==='ped'){t.down=4.5;t.panic=8;sparks(aim.point,0xe2d6a4,3);addHeat(.75);for(const p of peds)if(distance(p,t)<12)p.panic=5;}
 else{t.health-=w.damage;addHeat(t.police?.7:.3);sparks(aim.point);if(t.health<=0){t.disabled=8;t.speed=0;t.health=100;sparks(aim.point,0xf9bf7d,15);if(t.police)addHeat(.5);toast('车辆受损 · 数秒后自动修复');}}}
 if(weapon>=2)addHeat(.12);updateHUD();}
function completeMission(){if(missionStage===3)return;missionStage=3;cash+=750;toast('任务完成！+$750 · 现在自由探索三座城市');audio('reward');}
function jump(){if(activeCar){input.brake=true;return;}if(jumpHeight<.01){jumpVelocity=6.3;audio('jump');}}
function audio(type){if(!soundOn||!audioCtx)return;try{audioCtx.resume();const t=audioCtx.currentTime,g=audioCtx.createGain();g.connect(audioCtx.destination);const o=audioCtx.createOscillator();o.connect(g);if(type==='shot'||type==='smg'){let len=.09,b=audioCtx.createBuffer(1,Math.floor(audioCtx.sampleRate*len),audioCtx.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*Math.pow(1-i/a.length,3);let noise=audioCtx.createBufferSource();noise.buffer=b;let f=audioCtx.createBiquadFilter();f.type='lowpass';f.frequency.value=1800;noise.connect(f);f.connect(g);g.gain.setValueAtTime(type==='smg'?.035:.07,t);noise.start();return;}let freq={switch:440,melee:110,jump:240,crash:65,reward:660}[type]||280;o.type=type==='crash'?'triangle':'sine';o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(type==='reward'?990:freq*.55,t+.13);g.gain.setValueAtTime(.035,t);g.gain.exponentialRampToValueAtTime(.001,t+.17);o.start();o.stop(t+.18);}catch(e){}}
function toggleSoundV4(){soundOn=!soundOn;if(soundOn&&!audioCtx){try{audioCtx=new(window.AudioContext||window.webkitAudioContext)();engineOsc=audioCtx.createOscillator();engineOsc.type='triangle';engineGain=audioCtx.createGain();engineGain.gain.value=0;engineOsc.connect(engineGain);engineGain.connect(audioCtx.destination);engineOsc.start();}catch(e){soundOn=false;}}$('soundBtn').textContent='声音：'+(soundOn?'开启':'关闭');if(soundOn)audio('switch');}
function animateHuman(p,dt,moving,armed=false){p.phase+=dt*(moving?Math.max(5,moving*2.3):1);const swing=Math.sin(p.phase)*Math.min(.77,moving*.16);p.legs[0].rotation.x=swing;p.legs[1].rotation.x=-swing;p.body.position.y=moving?Math.abs(Math.sin(p.phase))*.055:Math.sin(worldTime*1.8+p.phase)*.014;p.arms[0].rotation.x=-swing*.65;p.arms[1].rotation.x=swing*.65;p.arms[0].rotation.z=.06;p.arms[1].rotation.z=-.06;if(armed){p.arms[1].rotation.x=weapon===1?-.4:-1.3;if(weapon===3)p.arms[0].rotation.x=-1.12;if(attackTime>0){if(weapon<2){p.arms[1].rotation.x=-1.1+Math.cos(attackTime*14)*.8;p.arms[1].rotation.z=-Math.sin(attackTime*12);p.gun.rotation.y=Math.sin(attackTime*14)*.9;}else p.gun.position.z=.38-Math.sin(attackTime*24)*.09;}else{p.gun.rotation.y=0;p.gun.position.z=.38;}}else if(attackTime>0&&p===player){p.arms[1].rotation.x=-1.6+Math.cos(attackTime*14)*.7;}}
function updatePlayer(dt){if(updateVault(dt))return;let x=input.x+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y=input.y+(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0);const automatic=navPath.length?navigationInput(dt):null;if(automatic){x=automatic.x;y=automatic.y;}let len=Math.hypot(x,y);if(len>1){x/=len;y/=len;}const sprint=!!automatic?.run||input.sprint||keys.has('shift');
 if(activeCar){const c=activeCar,throttle=y,steer=x,max=automatic?(sprint?18:9):(sprint?24:17);if(!navPath.length&&!keys.size&&Math.abs(y)<.01)c.speed*=Math.exp(-dt*5);let drag=(input.brake||keys.has(' '))?4.5:.85;c.speed+=throttle*(throttle*c.speed<0?17:8.2)*dt;c.speed*=Math.exp(-drag*dt);c.speed=clamp(c.speed,-7,max);if(Math.abs(c.speed)<.035)c.speed=0;if(Math.abs(c.speed)>.2)c.heading=wrap(c.heading+steer*Math.min(1.9,Math.abs(c.speed)*.14)*dt*Math.sign(c.speed));let old={lat:c.lat,lon:c.lon};let moved=moveWithCollision(c,c.heading,c.speed*dt,.95);if(moved<Math.abs(c.speed*dt)*.35&&Math.abs(c.speed)>2){const hitSpeed=Math.abs(c.speed);c.speed*=-.26;c.health-=hitSpeed*.30;audio('crash');sparks(nAt(c.lat,c.lon).multiplyScalar(R+.8),0xffd8a4,4);if(hitSpeed>10)hurt(2);}
 player.lat=c.lat;player.lon=c.lon;player.heading=c.heading;viewYaw=angleLerp(viewYaw,c.heading,dt*2.9);if(missionStage===1){driveDistance+=distance(old,c);if(driveDistance>=110){missionStage=2;toast('兜风完成 · 下车后击中 3 个青色训练靶');}}
 if(c.health<=0){c.health=100;c.disabled=7;enterExit();toast('车辆需要修理 · 换一辆继续出发');}
 }else{if(len>.08){const targetHeading=wrap(viewYaw+Math.atan2(x,y));player.heading=angleLerp(player.heading,targetHeading,dt*13);const speed=(sprint?6.5:3.4)*Math.min(1,len);const moved=moveWithCollision(player,targetHeading,speed*dt,.36);player.speed=moved/dt;}else player.speed=0;
 jumpVelocity-=15*dt;jumpHeight=Math.max(0,jumpHeight+jumpVelocity*dt);if(jumpHeight===0)jumpVelocity=0;place(player.root,player.lat,player.lon,player.heading,jumpHeight+.06);player.shadow.visible=jumpHeight<.4;animateHuman(player,dt,player.speed,weapon>0);}
 if((fireHeld||input.fire||keys.has('f'))&&!activeCar&&!activeJet)attack();if(reloadTime>0){reloadTime-=dt;if(reloadTime<=0){ammo[weapon]=weapons[weapon].clip;toast('装填完成');updateHUD();}}cooldown=Math.max(0,cooldown-dt);attackTime=Math.max(0,attackTime-dt);
}
function updateCars(dt){for(const c of cars){if(c.disabled>0){c.disabled-=dt;c.body.rotation.z=Math.sin(worldTime*5)*.015;c.driver.visible=false;if(c.disabled<=0){c.health=100;c.body.rotation.z=0;c.driver.visible=c.occupied;}place(c.root,c.lat,c.lon,c.heading,.06);continue;}
 if(!c.player){if(c.police&&wanted>=.8){const d=distance(c,player);const desired=headingTo(c,player);c.heading=angleLerp(c.heading,desired,dt*1.6);const speed=d>6?Math.min(12,5+wanted*2):d>2.8?4:0;c.speed=lerp(c.speed,speed,dt*2);let moved=moveWithCollision(c,c.heading,c.speed*dt,.95);if(moved<.001&&d>8)c.heading+=dt*2;if(d<2.9&&heatAge%3<dt){hurt(activeCar?2:6);audio('crash');}if(d>64&&heatAge>10){const p=movePoint(player,player.heading+Math.PI,28);if(!collides(p.lat,p.lon,1)){c.lat=p.lat;c.lon=p.lon;}}}
 else if(c.traffic){c.speed=Math.abs(c.cruise);c.heading=c.cruise>0?Math.PI/2:-Math.PI/2;const future=movePoint(c,c.heading,c.speed*dt);if(activeCar&&distance(future,activeCar)<4.5){c.speed=0;}else{c.lon=future.lon;}}
 else c.speed*=Math.exp(-dt*3);}
 place(c.root,c.lat,c.lon,c.heading,.06);c.body.rotation.x=lerp(c.body.rotation.x,c.player&&Math.abs(c.speed)>1?-.025:0,dt*4);for(const w of c.wheels)w.rotation.x+=c.speed*dt/.37;c.driver.visible=c.occupied;
 if(c.police){for(let j=0;j<c.beacon.length;j++)c.beacon[j].visible=wanted>.5?Math.floor(worldTime*7+j)%2===0:true;}
 if(c!==activeCar&&activeCar&&distance(c,activeCar)<2.25&&Math.abs(activeCar.speed)>4){const oldSpeed=activeCar.speed;activeCar.speed*=-.27;c.speed=0;c.health-=Math.abs(oldSpeed)*.8;audio('crash');sparks(nAt(c.lat,c.lon).multiplyScalar(R+1));if(c.police)addHeat(.4);}
 }}
function updatePeds(dt){for(const p of peds){if(p.down>0){p.down-=dt;p.body.rotation.z=lerp(p.body.rotation.z,Math.PI*.48,dt*8);p.body.position.y=.2;if(p.down<=0){p.body.rotation.z=0;p.body.position.y=0;p.panic=5;}continue;}let sp=p.panic>0?2.1:p.speed;p.panic=Math.max(0,p.panic-dt);if(activeCar&&distance(p,activeCar)<2&&Math.abs(activeCar.speed)>5){p.down=4;addHeat(.4);continue;}p.heading=p.panic>0?headingTo(player,p):Math.PI/2;moveWithCollision(p,p.heading,sp*dt,.3);place(p.root,p.lat,p.lon,p.heading,.06);animateHuman(p,dt,sp);if(p.panic>0){p.arms[0].rotation.z=-2.6;p.arms[1].rotation.z=2.6;}}
 for(const t of targets){t.hitTimer=Math.max(0,t.hitTimer-dt);t.face.rotation.z=Math.sin(worldTime*1.5)*.07;t.face.visible=t.hitTimer<=0;t.root.children[1].scale.y=1;}
}
function updateEffectsV4(dt){for(let i=fx.length-1;i>=0;i--){let f=fx[i];f.time-=dt;if(f.time<=0){scene.remove(f.root);if(f.type==='line')f.root.geometry.dispose();f.root.material.dispose();fx.splice(i,1);continue;}if(f.velocity)f.root.position.addScaledVector(f.velocity,dt);f.root.material.opacity=Math.min(1,f.time/f.max);if(f.type==='spark')f.root.scale.multiplyScalar(Math.exp(-dt*4));}}
let cameraInitialized=false;const camRay=new THREE.Raycaster();
function updateCamera(dt,force=false){const a=frame(player.lat,player.lon,viewYaw),anchor=nAt(player.lat,player.lon).multiplyScalar(R);let desired,target,up=a.n;
 if(!started){const t=worldTime*.035;desired=V(Math.sin(t+.50)*84,76,Math.cos(t+.50)*55);target=V(0,0,0);up=V(0,1,0);camera.fov=43;}
 else if(orbit){desired=anchor.clone().normalize().multiplyScalar(R*3.3).addScaledVector(a.f,-R*.5).addScaledVector(a.r,R*.12);target=V();up=a.f;camera.fov=47;}
 else{let dist=activeCar?8.7:6.2,height=activeCar?4.1:3.0;dist+=viewPitch*1.2;height+=viewPitch*3;target=anchor.clone().addScaledVector(a.n,activeCar?1.3:1.25).addScaledVector(a.f,activeCar?1.0:.5);desired=anchor.clone().addScaledVector(a.f,-dist).addScaledVector(a.n,height).addScaledVector(a.r,.55);let ray=desired.clone().sub(target);camRay.set(target,ray.clone().normalize());camRay.far=ray.length();let candidates=buildingMeshes.filter((m,i)=>buildings[i].center.distanceTo(anchor)<15);const hit=camRay.intersectObjects(candidates,false)[0];if(hit&&hit.distance<ray.length()){desired.copy(target).addScaledVector(ray.normalize(),Math.max(2.0,hit.distance-.35));desired.addScaledVector(a.n,.4);}camera.fov=53;}
 if(force||!cameraInitialized){camera.position.copy(desired);camera.up.copy(up);cameraInitialized=true;}else{camera.position.lerp(desired,1-Math.exp(-dt*5.0));camera.up.lerp(up,1-Math.exp(-dt*5)).normalize();}
 camera.lookAt(target);camera.updateProjectionMatrix();
 // The shadow's sun follows the local hemisphere to keep every side playable.
 const sunAnchor=started&&!orbit?anchor:V();light.position.copy(sunAnchor).addScaledVector(a.n,52).addScaledVector(a.r,-28).addScaledVector(a.f,15);light.target.position.copy(sunAnchor);light.target.updateMatrixWorld();
}
function updateHUD(){if(!player)return;document.body.dataset.gameState=JSON.stringify({started,menuOpen,city:cityId,character:charId,weapon,ammo:ammo[weapon],inCar:!!activeCar,carSpeed:activeCar?.speed||0,lat:player.lat,lon:player.lon,heading:player.heading,wanted,health,missionStage,driveDistance,targetHits,stolenCount,orbit,navNodes:navPath.length,running:navRunning,jumpHeight,jumpCount,vaultCount,vaulting:!!vault,buildingTypes:[...new Set(buildingKinds)],frames:frameCounter,renderMode:renderer.isSoftwareRenderer?'software':'webgl'});$('money').textContent='$ '+Math.round(cash).toLocaleString('en-US');$('health').style.width=health+'%';$('health').style.background=health<30?'#efa894':'var(--mint)';let starCount=Math.ceil(wanted);$('stars').innerHTML=Array.from({length:5},(_,i)=>i<starCount?'<span class="hot">★</span>':'★').join('');$('weaponLabel').textContent=activeCar?(activeCar.police?'警车':activeCar.type==='taxi'?'出租车':activeCar.type==='lowrider'?'低底盘轿车':'跑车'):weapons[weapon].name;$('ammoLabel').textContent=activeCar?'车辆状况 '+Math.round(activeCar.health)+'%':reloadTime>0?'装填中…':weapon>=2?ammo[weapon]+' / ∞ · '+weapons[weapon].en:(coarse?'点击攻击 · 切换武器':'点地走路 · 右下角切换武器');$('speed').style.display=activeCar?'block':'none';$('speedNumber').textContent=String(Math.round(Math.abs(activeCar?.speed||0)*3.6)).padStart(2,'0');setHTML('touchEnter',activeCar?'下车':'上 / 抢车');setHTML('touchFire',activeCar?'鸣笛':'攻击');
 if(missionStage===0){$('missionTitle').textContent='借一辆车，绕星球兜风';$('missionDesc').textContent='点路面走近车辆，点右下角「上 / 抢车」。';$('missionProgress').value=0;$('missionFoot').textContent='01 / 03 · 随时可以自由探索';}
 else if(missionStage===1){$('missionTitle').textContent='沿着弯曲街道兜一圈';$('missionDesc').textContent='驾驶 '+Math.min(110,Math.floor(driveDistance))+' / 110 米 · 直行加速，左右转向';$('missionProgress').value=driveDistance/110*100;$('missionFoot').textContent='02 / 03 · 小心建筑与来车';}
 else if(missionStage===2){$('missionTitle').textContent='下车，试试你的准头';$('missionDesc').textContent='命中青色训练靶 '+Math.min(targetHits,3)+' / 3 · 装备手枪，朝目标射击';$('missionProgress').value=targetHits/3*100;$('missionFoot').textContent='03 / 03 · 雷达青色圆点是训练靶';if(targetHits>=3)completeMission();}
 else{$('missionTitle').textContent='这颗小星球，随你探索';$('missionDesc').textContent='任务完成 +$750 · 换角色、换城市，继续自由漫游。';$('missionProgress').value=100;$('missionFoot').textContent='FREE ROAM · '+(stolenCount?'抢车 '+stolenCount+' 次 · ':'')+'训练靶命中 '+targetHits+' 次';}
 if(!activeCar)findNearestCar();const context=$('context');if(!orbit&&(activeCar||nearestCar)&&started){context.style.display='block';setText('contextText',activeCar?'下车':nearestCar.occupied?'抢这辆车':'驾驶这辆车');}else context.style.display='none';
 let ret=$('reticle');ret.style.display=weapon>=2&&!activeCar&&!orbit?'block':'none';aimTarget=weapon>=2&&!activeCar?pickTarget():null;ret.classList.toggle('lock',!!aimTarget);if(aimTarget){let p=aimTarget.point.clone().cityProject12(camera);ret.style.left=(p.x*.5+.5)*100+'%';ret.style.top=(-p.y*.5+.5)*100+'%';}else{ret.style.left='50%';ret.style.top='50%';}
 refreshOneHandHUD();
}
function drawRadar(){const c=$('radar'),g=c.getContext('2d'),W=c.width,mid=W/2,scale=4.0;g.clearRect(0,0,W,W);g.save();g.beginPath();g.arc(mid,mid,mid-2,0,TAU);g.clip();g.fillStyle='#183a36';g.fillRect(0,0,W,W);const a=frame(player.lat,player.lon,viewYaw),origin=nAt(player.lat,player.lon).multiplyScalar(R);function xy(lat,lon){const p=nAt(lat,lon).multiplyScalar(R).sub(origin);return [mid+p.dot(a.r)*scale,mid-p.dot(a.f)*scale];}g.lineCap='round';g.strokeStyle='#7d9a85';g.lineWidth=17;for(const lat of [-.58,0,.58]){g.beginPath();for(let i=0;i<=120;i++){const lon=i*TAU/120,p=xy(lat,lon);if(nAt(lat,lon).dot(nAt(player.lat,player.lon))<.65){g.moveTo(...p);continue;}if(i===0)g.moveTo(...p);else g.lineTo(...p);}g.stroke();}for(let i=0;i<4;i++){g.beginPath();for(let j=0;j<80;j++){let lat=-1.1+j*2.2/79,lon=i*Math.PI/2,p=xy(lat,lon);if(nAt(lat,lon).dot(nAt(player.lat,player.lon))<.45){g.moveTo(...p);continue;}j?g.lineTo(...p):g.moveTo(...p);}g.stroke();}g.fillStyle='#476c55';for(const b of buildings){if(distance(player,b)>42)continue;let p=xy(b.lat,b.lon);g.fillRect(p[0]-8,p[1]-8,16,16);}for(const t of targets){if(distance(player,t)>40)continue;let p=xy(t.lat,t.lon);g.fillStyle=t.hitTimer>0?'#547d6a':'#b4f5c5';g.beginPath();g.arc(...p,4,0,TAU);g.fill();}for(const c of cars){if(distance(player,c)>40)continue;let p=xy(c.lat,c.lon);g.fillStyle=c.police&&wanted>.5?'#ef9a8d':c===activeCar?'#f5ecc1':'#c5c9aa';g.fillRect(p[0]-3,p[1]-4,6,8);}g.save();g.translate(mid,mid);g.rotate(wrap(player.heading-viewYaw));g.fillStyle='#f2f4da';g.strokeStyle='#163c31';g.lineWidth=2;g.beginPath();g.moveTo(0,-9);g.lineTo(6,7);g.lineTo(0,4);g.lineTo(-6,7);g.closePath();g.fill();g.stroke();g.restore();g.restore();g.fillStyle='#d0e9cc';g.font='17px system-ui';g.textAlign='center';g.fillText('N',mid,22);}
function openMenuV7(tab='help'){menuOpen=true;fireHeld=false;input.fire=false;keys.clear();input.x=input.y=0;resetStick();$('menu').classList.add('open');document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('active',p.id===tab));if(engineGain)engineGain.gain.setTargetAtTime(0,audioCtx.currentTime,.1);}
function closeMenu(){menuOpen=false;$('menu').classList.remove('open');keys.clear();lastTime=performance.now()/1000;}
function startGameV6(){started=true;orbit=false;$('cover').classList.add('hidden');$('hud').classList.remove('inactive');$('touch').classList.add('playing');$('rotateHint').classList.add('playing');cameraInitialized=false;lastTime=performance.now()/1000;toast('连续环球地图 · 左摇杆走 / 跑 · 任务 / 载具在右上角');updateHUD();}
