// One-finger navigation, spherical A* paths and contextual low-wall vaults.
let navPath=[],navGoal=null,navRunning=false,gesture=null,lastTap={time:0,x:0,y:0},moveRing=null,vault=null,walls=[],vaultCount=0,jumpCount=0;
