 for(let k=0;k<7;k++){const base=k*TAU/7;add(['格罗夫街','夕阳弯道','市场街','运河路','影院路','山坡街','码头路'][k],Array.from({length:181},(_,i)=>{let lat=-1.015+i*2.03/180;return {lat,lon:wrap(base+.075*(Math.sin((lat+.14)*4+k*.9)-Math.sin(k*.9))+.022*Math.sin((lat+.14)*9))};}),false,k===0?7:6.1);}
 for(let k=0;k<3;k++){const center={lat:[.31,-.38,.83][k],lon:[.39,1.92,-1.13][k]};add(['花园新月路','仓库支路','瞭望台环路'][k],Array.from({length:101},(_,i)=>{let t=i/100*TAU;return {lat:center.lat+Math.sin(t)*.13,lon:wrap(center.lon+Math.cos(t)*.24)};}),true,5.5);}
