function streetPoint(s,index,side=0,direction=1){index=clamp(index,0,s.points.length-1);const p=s.points[index],next=s.points[clamp(index+direction,0,s.points.length-1)],prev=s.points[clamp(index-direction,0,s.points.length-1)];const h=distance(p,next)>.1?headingTo(p,next):headingTo(prev,p);return {...movePoint(p,h+Math.PI/2,side),heading:h};}
