function drawLegacyRadar(){const c=$('radar'),g=c.getContext('2d'),W=c.width,mid=W/2,scale=3.1,a=frame(player.lat,player.lon,viewYaw),origin=nAt(player.lat,player.lon).multiplyScalar(R);const xy=p=>{const d=nAt(p.lat,p.lon).multiplyScalar(R).sub(origin);return [mid-d.dot(a.r)*scale,mid-d.dot(a.f)*scale];};g.clearRect(0,0,W,W);g.save();g.beginPath();g.arc(mid,mid,mid-2,0,TAU);g.clip();g.fillStyle='#273c37';g.fillRect(0,0,W,W);g.lineCap='round';g.strokeStyle='#83958b';for(const s of streets){g.lineWidth=(s.width+1)*scale;g.beginPath();let connected=false;for(const p of s.points){const pt=xy(p);if(distance(player,p)>65){connected=false;continue;}if(!connected)g.moveTo(...pt);else g.lineTo(...pt);connected=true;}g.stroke();}g.fillStyle='#4e6959';for(const b of buildings)if(distance(player,b)<57){const p=xy(b);g.fillRect(p[0]-7,p[1]-7,14,14);}for(const p of [...targets,...cars,...peds.filter(x=>x.police||x===lockPed)]){if(distance(player,p)>55)continue;const xy0=xy(p);g.fillStyle=p===lockPed?'#ffce82':p.police?'#86b9fb':p.kind==='target'?'#b4f5c5':'#d4d9c1';g.beginPath();g.arc(...xy0,p.police?4:3,0,TAU);g.fill();}g.translate(mid,mid);g.rotate(-wrap(player.heading-viewYaw));g.fillStyle='#fff1c9';g.beginPath();g.moveTo(0,-10);g.lineTo(6,7);g.lineTo(0,4);g.lineTo(-6,7);g.fill();g.restore();}
function synthNote(freq,start,len,type,volume,slide=0){if(!audioCtx||!radioMaster)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,start);if(slide)o.frequency.exponentialRampToValueAtTime(freq*slide,start+len);g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(volume,start+.012);g.gain.exponentialRampToValueAtTime(.0001,start+len);o.connect(g);g.connect(radioMaster);o.start(start);o.stop(start+len+.02);o.onended=()=>{o.disconnect();g.disconnect();};}
function updateRadio(){if(!audioCtx||!soundOn||!radioStation||!started||menuOpen||wheelMode){if(radioMaster&&audioCtx)radioMaster.gain.setTargetAtTime(0,audioCtx.currentTime,.10);return;}if(!radioMaster){radioMaster=audioCtx.createGain();radioMaster.connect(audioCtx.destination);}radioMaster.gain.setTargetAtTime(.31,audioCtx.currentTime,.2);const now=audioCtx.currentTime;if(radioNext<now)radioNext=now+.025;const step=60/stationDefs[radioStation].bpm/2;for(let n=0;radioNext<now+.13&&n<8;n++){let k=radioBeat%16,root=[0,55,65.406,73.416][radioStation],scale=[1,1,1.5,1,1.25,1,1.5,1.125];if(k%4===0)synthNote(115,radioNext,.12,'sine',.22,.30);if(k%4===2)synthNote(155,radioNext,.08,'triangle',.07,.45);synthNote(root*scale[k%8],radioNext,step*.85,radioStation===1?'triangle':'sawtooth',.075);if(radioStation===2||k%2===0)synthNote(root*4*[1,1.25,1.5,2][Math.floor(k/2)%4],radioNext,step*.55,'sine',.038);synthNote(7000+(k%3)*900,radioNext,.025,'square',.006,.7);radioBeat++;radioNext+=step;}}

