function resetStick(){joystickPointer=null;input.x=input.y=0;input.sprint=false;$('stick').style.transform='translate(0px,0px)';$('joystick').classList.remove('running');}
function openWheel(mode){if(!started||menuOpen||orbit)return;wheelMode=mode;resetStick();input.fire=input.brake=false;keys.clear();stopNavigation();const items=mode==='weapon'?weapons.map((w,i)=>({name:w.name,tag:i<2?'∞':ammo[i]+' 发',index:i})):stationDefs.map((s,i)=>({name:s.name,tag:s.tag,index:i}));$('wheelTitle').textContent=mode==='weapon'?'选择武器':'选择电台';$('wheelHint').textContent='轻点选择 · 或按住按钮拖到扇区后松手';$('wheelItems').innerHTML=items.map((w,i)=>{const angle=-Math.PI/2+i*TAU/items.length,x=50+Math.cos(angle)*34,y=50+Math.sin(angle)*34;return `<button class="wheel-item ${(mode==='weapon'?weapon:radioStation)===i?'selected':''}" data-wheel-item="${i}" style="left:${x}%;top:${y}%"><strong>${mode==='weapon'?['✊','╱','▰','▥'][i]:['○','♫','≋','◈'][i]}</strong><b>${w.name}</b><small>${w.tag}</small></button>`;}).join('');$('wheel').classList.add('open');$('wheel').setAttribute('aria-hidden','false');document.body.classList.add('wheel-open');$('wheelItems').querySelectorAll('[data-wheel-item]').forEach(b=>b.onclick=()=>selectWheel(Number(b.dataset.wheelItem)));}
function closeWheel(){wheelMode=null;$('wheel').classList.remove('open');$('wheel').setAttribute('aria-hidden','true');document.body.classList.remove('wheel-open');lastTime=performance.now()/1000;}
function selectWheel(i){if(wheelMode==='weapon')setWeapon(i);else{radioStation=i;radioBeat=0;radioNext=0;if(i&&!soundOn)toggleSound();toast(stationDefs[i].name+' · '+stationDefs[i].tag);}closeWheel();}
function wheelIndexAt(x,y){const r=$('wheelItems').getBoundingClientRect(),dx=x-(r.left+r.width/2),dy=y-(r.top+r.height/2);if(Math.hypot(dx,dy)<r.width*.17)return -1;const angle=(Math.atan2(dy,dx)+Math.PI/2+TAU)%TAU;return Math.round(angle/(TAU/4))%4;}
function bindWheelButton(id,mode){const b=$(id);let held=null;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);openWheel(mode);held={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false,index:-1};});b.addEventListener('pointermove',e=>{if(!held||held.id!==e.pointerId||wheelMode!==mode)return;if(Math.hypot(e.clientX-held.x,e.clientY-held.y)>16){held.moved=true;held.index=wheelIndexAt(e.clientX,e.clientY);$('wheelItems').querySelectorAll('[data-wheel-item]').forEach(t=>t.classList.toggle('hover',Number(t.dataset.wheelItem)===held.index));}});b.addEventListener('pointerup',e=>{if(!held||held.id!==e.pointerId)return;if(held.moved&&held.index>=0)selectWheel(held.index);held=null;});b.addEventListener('pointercancel',()=>{held=null;closeWheel();});}
