function refreshLegacyHUD(){setText('touchEnter',activeCar?'下车':'上 / 抢车');if(!activeCar&&weapon<2)setText('ammoLabel','点人锁定 · 武器轮盘选枪');$('touchEnter').style.display=activeCar||nearestCar?'grid':'none';$('touchReload').style.display=weapon>=2&&!activeCar?'grid':'none';setText('touchStop',activeCar?'刹车':'解锁');$('touchStop').style.display=activeCar||lockPed?'grid':'none';setText('touchJump',activeCar?'手刹':'跳 / 翻');setText('touchFire',activeCar?'鸣笛':weapon<2?'攻击':'开火');setText('gestureHint',activeCar?'摇杆前推加速 · 左右转向 · 手刹漂移':'摇杆轻推走路 / 推到底跑 · 点人锁定 · 双击跳跃');setText('radioLabel',stationDefs[radioStation].name);$('speedFX').style.opacity=activeCar?String(clamp((Math.abs(activeCar.speed)-17)/25,0,.50)):'0';$('targetBadge').style.display=lockPed&&!activeCar?'block':'none';if(lockPed)setText('targetBadge',(lockPed.police?'巡警':lockPed.styleName||'路人')+' · '+Math.round(distance(player,lockPed))+'m'+(targetVisible(lockPed,weapons[weapon].range)?' · 已锁定':' · 超出射程 / 遮挡'));
 const state=JSON.parse(document.body.dataset.gameState||'{}');Object.assign(state,{version:'0.13.0',planetRadius:R,streets:streets.length,junctions:junctions.length,buildings:buildings.length,pedestrians:peds.length,pedestrianStyles:[...new Set(peds.map(p=>p.styleName))].length,footPolice:peds.filter(p=>p.police).length,policeCars:cars.filter(c=>c.police).length,radio:radioStation,wheel:wheelMode,locked:!!lockPed,lockCount,collisionCount,joystick:{x:input.x,y:input.y,running:input.sprint},navNodes:navPath.length,jumpCount,vaultCount,buildingTypes:[...new Set(buildingKinds)]});document.body.dataset.gameState=JSON.stringify(state);const near=peds.find(p=>p.root.visible&&targetVisible(p)&&distance(player,p)<15);if(near){const pt=nAt(near.lat,near.lon).multiplyScalar(R+1.18).cityProject12(camera);document.body.dataset.targetPoint=JSON.stringify({x:(pt.x*.5+.5)*innerWidth,y:(-pt.y*.5+.5)*innerHeight});}if(moveRing&&navGoal)moveRing.scale.setScalar(1+Math.sin(worldTime*5)*.1);if(missionStage===0)setText('missionDesc','前方有车 · 靠近后点「上 / 抢车」。');}
function renderCharacterCardsV4(){for(let id=0;id<3;id++){const c=$('portrait'+id);if(!c)continue;try{const r=new PocketSoftwareRenderer({canvas:c});r.setSize(240,230);const s=new THREE.Scene();s.background=new THREE.Color([0x829d80,0x859fba,0x879aa9][id]);s.add(new THREE.HemisphereLight(0xffffff,0x353b40,2));const human=makeCharacter(id);s.add(human.root);human.root.rotation.y=-.18;const cam=new THREE.PerspectiveCamera(28,240/230,.1,20);cam.position.set(.12,1.68,2.6);cam.lookAt(0,1.43,0);r.render(s,cam);c.style.width='100%';c.style.height='100%';}catch(e){console.info('Portrait preview unavailable',e.message);}}}

