const UP3=V(0,0,1),GRID_SIZE=12;
function fromNormal(n){n=n.clone().normalize();return {lat:Math.asin(clamp(n.z,-1,1)),lon:Math.atan2(n.x,n.y)};}
function movePoint(a,heading,meters){const f=frame(a.lat,a.lon,heading),angle=meters/R,n=f.n.clone().multiplyScalar(Math.cos(angle)).addScaledVector(f.f,Math.sin(angle)).normalize();return fromNormal(n);}
function transportedHeading(a,p,heading){const n0=nAt(a.lat,a.lon),n1=nAt(p.lat,p.lon),q=new THREE.Quaternion().setFromUnitVectors(n0,n1),f=frame(a.lat,a.lon,heading).f.applyQuaternion(q);return Math.atan2(f.dot(eastAt(p.lon)),f.dot(northAt(p.lat,p.lon)));}
