 b.district=id;b.facadeVariant=index%5;
 const iron=mat(0x3c4e53,{metalness:.35,roughness:.65}),cream=mat(id===1?0xffdfd0:0xc6baa5),accent=mat(id===1?0x4ac9d1:id===0?0x6d5748:0x6e8a96);
