  if(index%3===0){for(const side of [-1,1]){box(g,cream,side*w*.31,1.05,front+.14,.12,2.1,.18);box(g,accent,side*w*.31,1.62,front+.25,.54,.035,.06);}box(g,iron,0,.35,front+.36,w*.66,.055,.10);}
