 for(let i=2;i<38;i+=5)ribbon(points.slice(i,i+3).map(p=>[p.lat,p.lon]),.35,.145,paint);
 for(const i of [2,37]){const p=points[i];for(const sign of [-1,1]){const q=movePoint(p,heading+Math.PI/2,sign*3.4);const t=movePoint(q,heading,1.8);ribbon([[q.lat,q.lon],[t.lat,t.lon]],1.1,.15,paint);}}
