const detailedClothCache=new Map();
function humanCloth(key,color,pattern='plain'){
 const k=key+color+pattern;if(detailedClothCache.has(k))return detailedClothCache.get(k);
 const t=canvasTexture(512,512,(g,W,H)=>{
  const base='#'+new THREE.Color(color).getHexString();g.fillStyle=base;g.fillRect(0,0,W,H);
  // Woven threads stay subtle at distance, visible in the character inspection view.
  for(let y=0;y<H;y+=4){g.fillStyle=y%8?'#ffffff08':'#182b3620';g.fillRect(0,y,W,.8);}for(let x=0;x<W;x+=5){g.fillStyle='#ffffff07';g.fillRect(x,0,.7,H);}
  if(pattern==='hawaii'){
   for(let y=-20;y<H+70;y+=107)for(let x=-20;x<W+70;x+=110){const xx=x+(Math.floor(y/107)%2)*43,yy=y+18;g.save();g.translate(xx,yy);g.rotate(-.5+(x%3)*.3);g.strokeStyle='#195d79';g.lineWidth=2;g.beginPath();g.moveTo(-31,33);g.quadraticCurveTo(4,-3,15,-43);g.stroke();for(let j=0;j<8;j++){const by=28-j*9,bx=-26+j*5;for(const sign of [-1,1]){g.strokeStyle=j%2?'#235c76':'#216f89';g.lineWidth=3;g.beginPath();g.moveTo(bx,by);g.quadraticCurveTo(bx+sign*15,by-12,bx+sign*(22-j),by-22);g.stroke();}}g.fillStyle='#d0e8df';for(let j=0;j<5;j++){const a=j*TAU/5;g.beginPath();g.ellipse(25+Math.sin(a)*12,14+Math.cos(a)*12,6,12,-a,0,TAU);g.fill();}g.fillStyle='#f3d3ab';g.beginPath();g.arc(25,14,4,0,TAU);g.fill();g.restore();}
  }else if(pattern==='denim'){
   const wash=g.createLinearGradient(0,0,W,0);wash.addColorStop(0,'#0f294422');wash.addColorStop(.3,'#d7dbbd21');wash.addColorStop(.6,'#ffffff0b');wash.addColorStop(1,'#12283a33');g.fillStyle=wash;g.fillRect(0,0,W,H);g.setLineDash([3,3]);g.strokeStyle='#e3c28d80';g.lineWidth=1.5;for(const x of [22,27,482,487]){g.beginPath();g.moveTo(x,0);g.lineTo(x,H);g.stroke();}g.setLineDash([]);
  }else if(pattern==='rib'){g.strokeStyle='#9396883a';g.lineWidth=1;for(let x=0;x<W;x+=5){g.beginPath();g.moveTo(x,0);g.lineTo(x,H);g.stroke();}}
  // Shaped cloth folds; the shading is authored into fabric, not facial skin.
  for(let i=0;i<10;i++){const x=45+i*46;g.strokeStyle='#10283b0d';g.lineWidth=4;g.beginPath();g.moveTo(x,90);g.bezierCurveTo(x-18,190,x+12,300,x-7,455);g.stroke();g.strokeStyle='#ffffff11';g.lineWidth=2;g.stroke();}
 });
 const m=new THREE.MeshStandardMaterial({map:t,roughness:pattern==='denim'?.91:.84});detailedClothCache.set(k,m);return m;
}
