 if(!melee){const ray=new THREE.Raycaster(start,end.clone().sub(start).normalize(),.01,start.distanceTo(end)),hit=ray.intersectObjects(buildingMeshes,false)[0];if(hit){end=hit.point;if(aim&&start.distanceTo(end)<start.distanceTo(aim.point)-.25)aim=null;}spawnLine(start,end,weapon===7?0xf8db92:0xffe6b0);if(weapon===6)for(let i=0;i<4;i++)spawnLine(start,end.clone().addScaledVector(f.r,(rng()-.5)*.6).addScaledVector(f.n,(rng()-.5)*.5),0xe9d8ab);sparks(start,0xffe9b1,2);audio(weapon===3||weapon===7?'smg':'shot');addHeat(.12);}else{audio('melee');if(weapon===4)bladeTrail(f);}
