 const a=musicArrangements[station],step=60/stationDefs[station].bpm/4,k=index%16,bar=Math.floor(index/16),section=Math.floor(bar/8)%4,chord=a.chords[Math.floor(bar/2)%a.chords.length],root=a.root+chord[0],dur=step*(station===5?1.05:1),full=section===1||section===3;
