 const texture=canvasTexture(256,256,(g,W,H)=>{g.fillStyle='#'+new THREE.Color(d.skin).getHexString();g.fillRect(0,0,W,H);const shade=g.createLinearGradient(0,0,W,0);shade.addColorStop(0,'#3c261b3a');shade.addColorStop(.35,'#e8c2a000');shade.addColorStop(.52,'#f4d9b517');shade.addColorStop(.66,'#e8c2a000');shade.addColorStop(1,'#30231c45');g.fillStyle=shade;g.fillRect(0,0,W,H);for(let i=0;i<900;i++){g.fillStyle=i%2?'#fff3da07':'#3923190c';g.fillRect(rng()*W,rng()*H,1,1);}if(!d.female){const stubble=g.createLinearGradient(0,160,0,244);stubble.addColorStop(0,'#292b2800');stubble.addColorStop(1,id===2?'#292b2835':'#292b281b');g.fillStyle=stubble;g.fillRect(86,163,84,81);}});
