 [-.123,.035,.061,.010],[-.112,width*.66,.075,.011],[-.087,width*.87,.086,.008],[-.045,width*.97,.100,0],[.002,width,.107,-.003],[.034,width*.98,.108,-.005],[.070,width*.97,.105,-.008],[.105,width*.88,.094,-.012],[.130,width*.61,.065,-.012],[.143,.003,.003,-.012]
