 const hairGeo=profileMesh([[hairTop+.007,.001,.001,-.015],[hairTop,width*.67,.075,-.018],[hairTop-.018,width*.94,.102,-.018],[hairBase,width*1.01,.109,-.015]],npc?14:26);
