  if(!npc&&id===1)for(let i=0;i<5;i++){const strand=new THREE.Mesh(new THREE.CapsuleGeometry(.013,.087,2,7),mat(i%2?0x342a25:0x42352c));strand.rotation.x=.94;strand.rotation.z=-.24;strand.position.set(-.064+i*.028,.139,-.013);p.head.add(strand);}
