 if(d.hat||d.cap){const cap=mat(d.hat?0xc5aa77:d.police?0x243449:d.shirt);smoothOrb(p.head,cap,0,.141,-.012,d.hat?.139:.122,.039,.121);smoothOrb(p.head,cap,0,.123,.074,d.hat?.166:.109,.012,.088);}
