function damageVehicle(c,damage,pos){
 if(c.wrecked)return;c.health=Math.max(0,c.health-damage);c.traffic=false;c.speed*=.88;sparks(pos,0xf9dc9c,5);impactFeedback(pos,damage>65,c.health<=0?'车辆摧毁':'车身命中');addHeat(c.police?.8:.25);if(c.health<=0)destroyVehicle(c,pos);
}
function escapeWreck(c){
 if(job?.taxi===c||job?.passenger&&c===activeCar)cancelCurrentJob(false);
 if(c!==activeCar)return;activeCar=null;c.player=false;player.root.visible=true;let exit=null;for(let r=2.2;r<8&&!exit;r+=1.2)for(let i=0;i<12;i++){const p=movePoint(c,c.heading+i*TAU/12,r);if(!capsuleContact(p,.4,false,0,true)){exit=p;break;}}
 if(exit){player.lat=exit.lat;player.lon=exit.lon;}else{player.lat=c.lat;player.lon=c.lon;repairActor(player,.4,true);}player.heading=c.heading;place(player.root,player.lat,player.lon,player.heading,.08);setActorAttached(player,true);stopNavigation();jumpHeight=jumpVelocity=0;hurt(12);toast('车辆已损毁 · 寻找另一辆载具');
}
