// One active-world clock for signals, queues, crossing pedestrians and distant AI.
let signals10=[],trafficClock10=0,trafficStats10={stops:0,starts:0,crossings:0};
function phaseAt10(seconds,offset=0){const c=BAY_CONFIG10.traffic,durations=[c.greenSeconds,c.yellowSeconds,c.allRedSeconds,c.pedestrianSeconds,c.clearanceSeconds,c.greenSeconds,c.yellowSeconds,c.allRedSeconds,c.pedestrianSeconds,c.clearanceSeconds],total=durations.reduce((a,b)=>a+b,0);let t=((seconds+offset)%total+total)%total;for(let i=0;i<durations.length;i++){if(t<durations[i])return {index:i,elapsed:t,remaining:durations[i]-t,a:i===0?'green':i===1?'yellow':'red',b:i===5?'green':i===6?'yellow':'red',ped:i===3||i===8,clearing:i===4||i===9};t-=durations[i];}return {a:'red',b:'red',ped:false,clearing:true,index:9,remaining:0};}
function setupSignals10(){signals10=[];trafficClock10=0;trafficStats10={stops:0,starts:0,crossings:0};const candidates=junctions.filter(j=>!streets[j.a].pedestrian10&&!streets[j.b].pedestrian10&&islandField9(j.lat,j.lon)<.87&&Math.abs(j.lat)<1.1).map(j=>{const a=streetPoint(streets[j.a],j.ia).heading,b=streetPoint(streets[j.b],j.ib).heading;return {...j,headings:[a,b],angle:Math.abs(Math.sin(a-b))};}).filter(j=>j.angle>.7);const targets=[localPoint9(beach9,24,13),...districtAnchors7,localPoint9(beach9,47,13),localPoint9(islandDefs9[0],25,30)];for(const target of targets){const j=candidates.filter(j=>signals10.every(s=>distance(s,j)>24)).sort((a,b)=>distance(a,target)-distance(b,target))[0];if(!j)continue;signals10.push({...j,id:signals10.length,stopRadius:Math.max(streets[j.a].width,streets[j.b].width)/2+3.3,offset:signals10.length*3.7,crossers:new Set(),lamps:[],pedLamps:[]});if(signals10.length>=BAY_CONFIG10.traffic.signalLimit)break;}}
