function updateSignalsVisual10(){for(const s of signals10){const state=signalState10(s);for(const lamp of s.lamps){const color=lamp.axis?state.b:state.a;lamp.materials.forEach((m,i)=>m.color.setHex(['red','yellow','green'][i]===color?[0xe58468,0xe3bb68,0x8ec9a5][i]:0x354c43));}for(const m of s.pedLamps)m.color.setHex(state.ped?0x9ed4a5:state.clearing&&Math.floor(trafficClock10*3)%2?0xe0b478:0xab7464);}}
